#define CHECK(v,n) if(!(v)){printf("test_tls_policy: FAIL %d\n",(n));return(n);}
typedef struct policy_backend{pst_u32 capabilities;}policy_backend;
typedef struct policy_runtime{policy_backend *backend;}policy_runtime;
typedef struct policy_connection{policy_backend *backend;pst_u32 min_version,max_version,alpn_requirement;pst_u8 alpn[32];pst_size alpn_size;pst_internal_diagnostic diagnostic;}policy_connection;
